```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, state_read};

struct Node;

fn encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Enrichment record (approved extra grant). RunInfo has no free-text
        // field, so its date is used as the query text. The result is
        // deliberately not used: it does not affect the output.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            encode(&info.date)
        );
        let _ = http_client::fetch(&url);

        let urls = state_read::get("urls")
            .map(|s| {
                s.lines()
                    .map(|l| l.trim())
                    .filter(|l| !l.is_empty())
                    .map(|l| l.to_string())
                    .collect::<Vec<String>>()
            })
            .unwrap_or_default();

        SubscriptionList { urls }
    }
}

export!(Node);
```

Two assumptions to check:

- **Enrichment query:** `RunInfo` has no text field, so I used `info.date` as the `q=` value.
- **State key:** the spec doesn't name the key in the `subscriptions` store, so I read `"urls"` and split it into one URL per line.

The enrichment response is discarded, so the output is unchanged. I used `fetch` rather than `get` so a transport failure doesn't trap the node.

